/**
 * Menus display a list of actions or options that a user can choose.
 */
export const Menu = /*#__PURE__*/ (forwardRef as forwardRefType)(function Menu<T>(
  props: MenuProps<T>,
  ref: DOMRef<HTMLDivElement>
) {
  [props, ref] = useSpectrumContextProps(props, ref, MenuContext);
  let {
    isSubmenu,
    size: ctxSize,
    isVirtualized: isParentVirtualized
  } = useContext(InternalMenuContext);
  let {
    children,
    size = ctxSize,
    UNSAFE_style,
    UNSAFE_className,
    styles,
    hideLinkOutIcon = false,
    items,
    loadingState,
    onLoadMore,
    isVirtualized = isParentVirtualized
  } = props;
  let ctx = useContext(InternalMenuTriggerContext);
  let inPopover = useContext(InPopoverContext);
  let stringFormatter = useLocalizedStringFormatter(intlMessages, '@react-spectrum/s2');
  let scale = useScale();

  let menuLoadingCircle = (
    <AriaMenuLoadMoreItem
      isLoading={loadingState === 'loadingMore'}
      onLoadMore={onLoadMore}
      className={loadingWrapperStyles}>
      <ProgressCircle
        isIndeterminate
        size="S"
        styles={progressCircleStyles}
        aria-label={stringFormatter.format('menu.loadingMore')}
      />
    </AriaMenuLoadMoreItem>
  );

  let renderer;
  if (typeof children === 'function' && items) {
    renderer = (
      <>
        <Collection items={items} dependencies={props.dependencies}>
          {children}
        </Collection>
        {menuLoadingCircle}
      </>
    );
  } else {
    renderer = (
      <>
        {children}
        {menuLoadingCircle}
      </>
    );
  }

  let isPopover = (ctx || isSubmenu) && !inPopover;
  let menuContent = (
    <AriaMenu
      {...props}
      className={menu(
        {size, isPopover, isVirtualized},
        isPopover
          ? null
          : mergeStyles(
              // if in user provided popover use their width instead of applying a min to the menu
              virtualizedMenuWidth({isVirtualized: isVirtualized && !inPopover}),
              styles
            )
      )}
      renderEmptyState={() =>
        loadingState === 'loading' ? (
          <div className={loadingWrapperStyles}>
            <ProgressCircle
              isIndeterminate
              size="S"
              styles={progressCircleStyles}
              aria-label={stringFormatter.format('menu.loading')}
            />
          </div>
        ) : (
          <span className={emptyStateText({size})}>{stringFormatter.format('menu.noResults')}</span>
        )
      }>
      {renderer}
    </AriaMenu>
  );

  let menuWithVirtualizer = isVirtualized ? (
    <Virtualizer
      layout={ListLayout}
      layoutOptions={{
        estimatedRowSize: ROW_HEIGHTS[size][scale],
        estimatedHeadingSize: ROW_HEIGHTS[size][scale],
        padding: 8
      }}>
      {menuContent}
    </Virtualizer>
  ) : isParentVirtualized ? (
    //  if user doesnt want their submenu to be virtualized we need to clear context from parent
    <CollectionRendererContext.Provider value={DefaultCollectionRenderer}>
      {menuContent}
    </CollectionRendererContext.Provider>
  ) : (
    menuContent
  );

  let content = (
    <InternalMenuContext.Provider value={{size, isSubmenu: true, hideLinkOutIcon, isVirtualized}}>
      <Provider
        values={[
          [HeaderContext, {styles: sectionHeader({size, isVirtualized})}],
          [
            HeadingContext,
            {
              // @ts-ignore
              role: 'presentation',
              styles: sectionHeading
            }
          ],
          [
            TextContext,
            {
              slots: {
                description: {styles: description({size, isFocused: false, isDisabled: false})}
              }
            }
          ],
          [InPopoverContext, false]
        ]}>
        {menuWithVirtualizer}
      </Provider>
    </InternalMenuContext.Provider>
  );

  if (isPopover) {
    return (
      <Popover ref={ref} padding="none" hideArrow>
        <div
          style={UNSAFE_style}
          className={
            (UNSAFE_className || '') +
            mergeStyles(wrappingDiv, virtualizedMenuWidth({isVirtualized}), styles)
          }>
          {content}
        </div>
      </Popover>
    );
  }

  return content;
});

